// Package tunnel manages the Cloudflare Tunnel connector that lets a server
// be reached without a public IPv4 address or open ports.
//
// The connector is a Compose project ("ki-tunnel") generated by the agent and
// run with host networking. Cloudflare terminates TLS and forwards each public
// hostname through the tunnel to the edge in behind mode. The tunnel's ingress
// is managed remotely in Cloudflare; the agent only holds the tunnel token.
// The token is handed to cloudflared as a read-only mounted file (--token-file,
// cloudflared 2025.4.0 or later), so it appears neither in the command line
// nor in the container environment. The pure generator ([Compose]) lives in
// this file; [Manager] drives it.
package tunnel

import (
	"encoding/json"
	"fmt"
	"path"
	"strings"
)

// DefaultImage is the pinned connector image.
const DefaultImage = "cloudflare/cloudflared:2026.10.0"

// ProjectName is the Compose project of the tunnel.
const ProjectName = "ki-tunnel"

// Labels on the tunnel container. It carries ki.managed but, being a system
// component, no project label.
const (
	// LabelComponent identifies system components (shared with the edge).
	LabelComponent = "ki.component"
	// ComponentTunnel is the LabelComponent value of the tunnel.
	ComponentTunnel = "tunnel"
	// labelGeneration changes whenever a new token is stored, so Compose
	// recreates the container (cloudflared reads the token only at start).
	labelGeneration = "ki.tunnel.generation"
)

// Paths inside the connector container.
const (
	ctrSecretDir = "/etc/cloudflared"
	ctrTokenFile = ctrSecretDir + "/token"
)

// ComposeOptions parameterize [Compose].
type ComposeOptions struct {
	Image string
	// SecretDir is the absolute host directory holding the token file; it is
	// mounted read-only at /etc/cloudflared.
	SecretDir string
	// MetricsPort is the loopback port of the readiness endpoint.
	MetricsPort int
	// Generation is an opaque value that changes with each new token.
	Generation string
	// UID and GID run the container as the owner of the (0600) token file,
	// so no capability to override file permissions is needed.
	UID, GID int
}

// Compose renders the Compose file of the connector. The token is not part of
// it: only the path of the mounted token file.
func Compose(o ComposeOptions) ([]byte, error) {
	if o.Image == "" || !path.IsAbs(o.SecretDir) || strings.ContainsAny(o.SecretDir, "\x00\n") ||
		o.MetricsPort < 1 || o.MetricsPort > 65535 || o.UID < 0 || o.GID < 0 {
		return nil, fmt.Errorf("tunnel: invalid compose options")
	}
	svc := map[string]any{
		"image":        o.Image,
		"network_mode": "host",
		"restart":      "unless-stopped",
		"read_only":    true,
		"user":         fmt.Sprintf("%d:%d", o.UID, o.GID),
		"tmpfs":        []string{"/tmp"},
		"security_opt": []string{"no-new-privileges:true"},
		"cap_drop":     []string{"ALL"},
		"command": []string{
			"tunnel", "--no-autoupdate", "--metrics", fmt.Sprintf("127.0.0.1:%d", o.MetricsPort),
			"run", "--token-file", ctrTokenFile,
		},
		"labels": map[string]string{
			"ki.managed":    "true",
			LabelComponent:  ComponentTunnel,
			labelGeneration: o.Generation,
		},
		"volumes": []any{map[string]any{
			"type": "bind", "source": o.SecretDir, "target": ctrSecretDir, "read_only": true,
			"bind": map[string]any{"create_host_path": false},
		}},
	}
	doc := map[string]any{"name": ProjectName, "services": map[string]any{"cloudflared": svc}}
	b, err := json.MarshalIndent(doc, "", "  ") // map keys are sorted
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}
